using System.ComponentModel.DataAnnotations;
namespace LocadoraVeiculos.DTOs;
public class FabricanteDto { [Required, StringLength(100)] public string Nome { get; set; } = string.Empty; }
public class VeiculoDto { [Required] public int FabricanteId { get; set; } [Required, StringLength(100)] public string Modelo { get; set; } = string.Empty; [Range(1900,2100)] public int AnoFabricacao { get; set; } [Range(0,double.MaxValue)] public decimal Quilometragem { get; set; } [Required, StringLength(10)] public string Placa { get; set; } = string.Empty; }
public class ClienteDto { [Required, StringLength(150)] public string Nome { get; set; } = string.Empty; [Required, StringLength(11,MinimumLength=11)] public string CPF { get; set; } = string.Empty; [Required,EmailAddress,StringLength(150)] public string Email { get; set; } = string.Empty; [StringLength(20)] public string Telefone { get; set; } = string.Empty; }
public class AluguelDto { [Required] public int ClienteId { get; set; } [Required] public int VeiculoId { get; set; } public DateTime DataInicio { get; set; } public DateTime DataPrevistaDevolucao { get; set; } public DateTime? DataDevolucao { get; set; } [Range(0,double.MaxValue)] public decimal QuilometragemInicial { get; set; } [Range(0,double.MaxValue)] public decimal? QuilometragemFinal { get; set; } [Range(0,double.MaxValue)] public decimal ValorDiaria { get; set; } [Range(0,double.MaxValue)] public decimal ValorTotal { get; set; } }
public class PagamentoDto { [Required] public int AluguelId { get; set; } public DateTime DataPagamento { get; set; } [Range(0.01,double.MaxValue)] public decimal Valor { get; set; } [Required,StringLength(30)] public string FormaPagamento { get; set; } = string.Empty; }
